questions.uml_mutation:
class PercentageRule {
    -int rolloutPercentage
}
class UserMatchRule {
    -String[] targetUserIds
}
TargetingRule <|-- PercentageRule
TargetingRule <|-- UserMatchRule

class EvaluationContext {
    -String userId
    -Map attributes
}
TargetingRule ..> EvaluationContext : requires

class TargetingRule {
    +evaluate(EvaluationContext context) : boolean
}
class PercentageRule {
    +evaluate(EvaluationContext context) : boolean
}
class UserMatchRule {
    +evaluate(EvaluationContext context) : boolean
}

class CompositeRule {
    -String logicalOperator
    +evaluate(EvaluationContext context) : boolean
}
TargetingRule <|-- CompositeRule
CompositeRule "1" *-- "*" TargetingRule : aggregates_logic

class FlagObserver {
    <<interface>>
    +onFlagUpdated(FeatureFlag flag)
}
FeatureFlag --> FlagObserver : notifies
